select

from t_share_resource
where project_id = #{projectId}
and resource_id = #{resourceId}
and workspace_id = #{workspaceId}

select
from t_share_resource where resource_id in ( select resource_id from t_share_scope where project_id = #{projectId} and (workspace_id = #{authWorkspaceId} or (workspace_id = 'all')) )
and (resource_type = 'controller' or resource_type = 'workflow')
and resource_type = #{resourceType}
and resource_name like concat('%', trim(lower(#{resourceName})), '%')
and workspace_id != #{authWorkspaceId} order by update_time desc

select

from t_share_resource
where trace_id = #{traceId}
and resource_type = #{resourceType}
and project_id = #{projectId}
and resource_id in
(
select resource_id
from t_share_scope
where project_id = #{projectId}
and (workspace_id = #{authWorkspaceId} or (workspace_id = 'all'))
)
and workspace_id != #{authWorkspaceId}
order by update_time desc

select
from t_share_resource where resource_id in
#{resourceId}

select

from t_share_resource
where project_id = #{projectId}
and workspace_id = #{workspaceId}

    and (resource_type = 'controller' or resource_type = 'workflow')


    and resource_type = #{resourceType}


    and resource_name like concat('%', trim(lower(#{resourceName})), '%')

